const data = JSON.parse(FILE_CONTENT);
const fs = require('fs');
let out = [];
for (let p=136; p<=185; p++) {
  out.push(`=== PDF PAGE ${p} (printed ${p-11}) ===\n` + data[p].text);
}
const full = out.join('\n\n');
fs.writeFileSync('/tmp/ch3_full.txt', full);
console.log('total chars', full.length);
// find lines that look like headers: short, many caps, or numbered like "3.1"
const lines = full.split('\n');
lines.forEach((l,i)=>{
  const t = l.trim();
  if (t.length>0 && t.length<70) {
    const capsRatio = (t.replace(/[^A-Za-z]/g,'').length>0) ? (t.replace(/[^A-Z]/g,'').length / t.replace(/[^A-Za-z]/g,'').length) : 0;
    if (capsRatio > 0.8 && /[A-Z]{4,}/.test(t)) {
      console.log(i, JSON.stringify(t));
    }
  }
});

